SELECT 
  id,
  name,
  phone_number AS phoneNumber,
  email
  FROM customer
  WHERE name = #{name}
    AND phone_number = #{phoneNumber}
    AND email = #{email}
   LIMIT 1

mapper.insert:

INSERT INTO customer(
 name,
 phone_number,
 email
 )
VALUES (
 #{name},
 #{phoneNumber},
 #{email}
 )
